<script lang="ts">
	import type { CommentsRequest } from '$lib/components/comments/CommentsPanel.svelte';
	export let onComment: (request: CommentsRequest) => void;
	import CommentButton from '$lib/components/comments/CommentButton.svelte';
	import LockClosed from '$lib/components/icons/LockClosed.svelte';
	import { getContext } from 'svelte';

	import Dropdown from '$lib/components/common/Dropdown.svelte';
	import DropdownMenu from '$lib/components/common/DropdownMenu.svelte';
	import GarbageBin from '$lib/components/icons/GarbageBin.svelte';
	import Pencil from '$lib/components/icons/Pencil.svelte';
	import Tooltip from '$lib/components/common/Tooltip.svelte';
	import Tags from '$lib/components/chat/Tags.svelte';
	import Share from '$lib/components/icons/Share.svelte';
	import ArchiveBox from '$lib/components/icons/ArchiveBox.svelte';
	import DocumentDuplicate from '$lib/components/icons/DocumentDuplicate.svelte';
	import Download from '$lib/components/icons/Download.svelte';
	import ArrowUpCircle from '$lib/components/icons/ArrowUpCircle.svelte';
	import Pin from '$lib/components/icons/Pin.svelte';
	import PinSlash from '$lib/components/icons/PinSlash.svelte';

	import {
		config,
		user as currentUser,
		pinnedModels,
		settings,
		visibleControls
	} from '$lib/stores';
	import Link from '$lib/components/icons/Link.svelte';
	import { resolveLocalizedModelName } from '$lib/utils/localizedContent';

	const i18n = getContext<any>('i18n');

	export let user;
	export let model;

	export let editHandler: Function;
	export let shareHandler: Function;
	export let cloneHandler: Function;
	export let exportHandler: Function;
	export let copyLinkHandler: Function;

	export let hideHandler: Function;
	export let pinModelHandler: Function;
	export let deleteHandler: Function;
	export let accessHandler: (() => void) | null = null;
	export let onClose: Function;

	export let writeAccess: boolean = true;

	let show = false;

	const runAndClose = async (handler: Function) => {
		show = false;
		await handler();
	};
</script>

<Dropdown
	bind:show
	onOpenChange={(state) => {
		if (state === false) {
			onClose();
		}
	}}
>
	<Tooltip content={$i18n.t('More')}>
		<button
			type="button"
			class="focus-ring rounded-lg"
			aria-label={`${$i18n.t('More')}: ${resolveLocalizedModelName(model, $i18n.language)}`}
			aria-haspopup="menu"
			aria-expanded={show}
			on:click={(e) => {
				e.stopPropagation();
				show = !show;
			}}
		>
			<slot />
		</button>
	</Tooltip>

	<div slot="content">
		<DropdownMenu className="min-w-[10.625rem]">
			{#if writeAccess}
				<button
					class="select-none flex h-[1.6875rem] w-full cursor-pointer items-center gap-2 rounded-xl bg-transparent px-2 text-[0.8125rem] hover:text-gray-900 dark:hover:text-gray-100"
					on:click={() => runAndClose(editHandler)}
				>
					<Pencil />
					<div class="flex items-center">{$i18n.t('Edit')}</div>
				</button>
			{/if}
			<CommentButton
				{onComment}
				modal
				menu
				resource={{ resource_type: 'model', resource_id: model.id }}
				onOpen={() => (show = false)}
			/>
			{#if accessHandler && writeAccess}
				<button
					type="button"
					class="select-none flex h-[1.6875rem] w-full cursor-pointer items-center gap-2 rounded-xl bg-transparent px-2 text-[0.8125rem] hover:text-gray-900 dark:hover:text-gray-100"
					on:click={() => {
						runAndClose(() => accessHandler?.());
					}}
				>
					<LockClosed className="size-3.5" />
					<div class="flex items-center">{$i18n.t('Access')}</div>
				</button>
			{/if}

			{#if writeAccess}
				<button
					class="select-none flex h-[1.6875rem] w-full cursor-pointer items-center gap-2 rounded-xl bg-transparent px-2 text-[0.8125rem] hover:text-gray-900 dark:hover:text-gray-100"
					on:click={() => runAndClose(hideHandler)}
				>
					{#if model?.meta?.hidden ?? false}
						<svg
							xmlns="http://www.w3.org/2000/svg"
							fill="none"
							viewBox="0 0 24 24"
							stroke-width="1.5"
							stroke="currentColor"
							class="size-4"
						>
							<path
								stroke-linecap="round"
								stroke-linejoin="round"
								d="M3.98 8.223A10.477 10.477 0 0 0 1.934 12C3.226 16.338 7.244 19.5 12 19.5c.993 0 1.953-.138 2.863-.395M6.228 6.228A10.451 10.451 0 0 1 12 4.5c4.756 0 8.773 3.162 10.065 7.498a10.522 10.522 0 0 1-4.293 5.774M6.228 6.228 3 3m3.228 3.228 3.65 3.65m7.894 7.894L21 21m-3.228-3.228-3.65-3.65m0 0a3 3 0 1 0-4.243-4.243m4.242 4.242L9.88 9.88"
							/>
						</svg>
					{:else}
						<svg
							xmlns="http://www.w3.org/2000/svg"
							fill="none"
							viewBox="0 0 24 24"
							stroke-width="1.5"
							stroke="currentColor"
							class="size-4"
						>
							<path
								stroke-linecap="round"
								stroke-linejoin="round"
								d="M2.036 12.322a1.012 1.012 0 0 1 0-.639C3.423 7.51 7.36 4.5 12 4.5c4.638 0 8.573 3.007 9.963 7.178.07.207.07.431 0 .639C20.577 16.49 16.64 19.5 12 19.5c-4.638 0-8.573-3.007-9.963-7.178Z"
							/>
							<path
								stroke-linecap="round"
								stroke-linejoin="round"
								d="M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z"
							/>
						</svg>
					{/if}

					<div class="flex items-center">
						{#if model?.meta?.hidden ?? false}
							{$i18n.t('Show Model')}
						{:else}
							{$i18n.t('Hide Model')}
						{/if}
					</div>
				</button>
			{/if}

			{#if $visibleControls['models.pin']}
				<button
					class="select-none flex h-[1.6875rem] w-full cursor-pointer items-center gap-2 rounded-xl bg-transparent px-2 text-[0.8125rem] hover:text-gray-900 dark:hover:text-gray-100"
					on:click={() => runAndClose(() => pinModelHandler(model?.id))}
				>
					{#if $pinnedModels.includes(model?.id)}
						<PinSlash />
					{:else}
						<Pin />
					{/if}

					<div class="flex items-center">
						{#if $pinnedModels.includes(model?.id)}
							{$i18n.t('Hide from Sidebar')}
						{:else}
							{$i18n.t('Keep in Sidebar')}
						{/if}
					</div>
				</button>
			{/if}

			{#if writeAccess}
				<button
					class="select-none flex h-[1.6875rem] w-full cursor-pointer items-center gap-2 rounded-xl bg-transparent px-2 text-[0.8125rem] hover:text-gray-900 dark:hover:text-gray-100"
					on:click={() => runAndClose(cloneHandler)}
				>
					<DocumentDuplicate />

					<div class="flex items-center">{$i18n.t('Clone')}</div>
				</button>
			{/if}

			{#if writeAccess}
				<hr class="border-gray-50/30 dark:border-gray-800/30 my-1" />
			{/if}

			<button
				class="select-none flex h-[1.6875rem] w-full cursor-pointer items-center gap-2 rounded-xl bg-transparent px-2 text-[0.8125rem] hover:text-gray-900 dark:hover:text-gray-100"
				on:click={() => runAndClose(copyLinkHandler)}
			>
				<Link />

				<div class="flex items-center">{$i18n.t('Copy Link')}</div>
			</button>

			{#if writeAccess && ($currentUser?.role === 'admin' || $currentUser?.permissions?.workspace?.models_export)}
				<button
					class="select-none flex h-[1.6875rem] w-full cursor-pointer items-center gap-2 rounded-xl bg-transparent px-2 text-[0.8125rem] hover:text-gray-900 dark:hover:text-gray-100"
					on:click={() => runAndClose(exportHandler)}
				>
					<Download />

					<div class="flex items-center">{$i18n.t('Export')}</div>
				</button>
			{/if}

			{#if writeAccess && $config?.features.enable_community_sharing}
				<button
					class="select-none flex h-[1.6875rem] w-full cursor-pointer items-center gap-2 rounded-xl bg-transparent px-2 text-[0.8125rem] hover:text-gray-900 dark:hover:text-gray-100"
					on:click={() => runAndClose(shareHandler)}
				>
					<Share />
					<div class="flex items-center">{$i18n.t('Share')}</div>
				</button>
			{/if}

			{#if writeAccess}
				<hr class="border-gray-50/30 dark:border-gray-800/30 my-1" />

				<button
					class="select-none flex h-[1.6875rem] w-full cursor-pointer items-center gap-2 rounded-xl bg-transparent px-2 text-[0.8125rem] hover:text-gray-900 dark:hover:text-gray-100"
					on:click={() => runAndClose(deleteHandler)}
				>
					<GarbageBin />
					<div class="flex items-center">{$i18n.t('Delete')}</div>
				</button>
			{/if}
		</DropdownMenu>
	</div>
</Dropdown>
